import os
import hashlib
import hmac
from flask import Flask, request, jsonify, abort
from functools import wraps
from pathlib import PurePosixPath
import re

app = Flask(__name__)

# Configuration loaded from environment
BASE_STORAGE_DIR = os.environ.get('STORAGE_ROOT', '/var/mobile_assets')
API_SECRET = os.environ.get('API_SECRET')
if not API_SECRET:
    # Fail closed rather than fall back to a known/hard-coded secret
    raise RuntimeError('API_SECRET environment variable must be set to a strong, unique value')
ALLOW_NESTED_PATHS = os.environ.get('ALLOW_NESTED', 'false').lower() == 'true'
PATH_ENCODING = os.environ.get('PATH_ENCODING', 'utf-8')
NORMALIZE_UNICODE = os.environ.get('NORMALIZE_UNICODE', 'NFC')


def verify_hmac_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token')
        timestamp = request.headers.get('X-Timestamp')
        if not token or not timestamp:
            abort(401)
        expected = hmac.new(
            API_SECRET.encode(),
            timestamp.encode(),
            hashlib.sha256
        ).hexdigest() if hasattr(hmac, 'new') else hmac.new(
            API_SECRET.encode(), timestamp.encode(), hashlib.sha256
        ).hexdigest()
        # Use compare_digest to prevent timing attacks
        if not hmac.compare_digest(token, expected):
            abort(403)
        return f(*args, **kwargs)
    return decorated


class PathSanitizer:
    """Multi-layer path sanitization for mobile asset requests."""

    BLOCKED_PATTERNS = [
        re.compile(r'\.\./'),
        re.compile(r'/\.\./'),
        re.compile(r'\.\.\\'),
        re.compile(r'%2e%2e', re.IGNORECASE),
        re.compile(r'%252e', re.IGNORECASE),
    ]

    ALLOWED_EXTENSIONS = {'.png', '.jpg', '.jpeg', '.gif', '.svg', '.webp', '.json', '.mp4'}

    def __init__(self, base_dir, allow_nested=False, encoding='utf-8'):
        self.base_dir = os.path.realpath(base_dir)
        self.allow_nested = allow_nested
        self.encoding = encoding

    def _check_blocked_patterns(self, path_str):
        for pattern in self.BLOCKED_PATTERNS:
            if pattern.search(path_str):
                return False
        return True

    def _validate_extension(self, path_str):
        _, ext = os.path.splitext(path_str)
        return ext.lower() in self.ALLOWED_EXTENSIONS

    def _normalize_path_components(self, path_str):
        """Normalize path by resolving components safely."""
        import unicodedata
        normalized = unicodedata.normalize(NORMALIZE_UNICODE, path_str)
        # Decode any percent-encoded characters for consistent checking
        try:
            from urllib.parse import unquote
            decoded = unquote(normalized, encoding=self.encoding)
        except Exception:
            decoded = normalized
        return decoded

    def resolve_safe_path(self, user_path):
        """Resolve user-provided path ensuring it stays within base_dir.

        Returns the resolved absolute path or None if unsafe.
        """
        if not user_path:
            return None

        # Step 1: Normalize unicode and decode percent-encoding
        normalized = self._normalize_path_components(user_path)

        # Step 2: Check blocked traversal patterns
        if not self._check_blocked_patterns(normalized):
            return None

        # Step 3: Validate extension
        if not self._validate_extension(normalized):
            return None

        # Step 4: Strip leading slashes to make relative
        clean_path = normalized.lstrip('/')

        # Step 5: If nested paths not allowed, reject any slashes
        if not self.allow_nested and '/' in clean_path:
            return None

        # Step 6: Construct full path and verify containment
        candidate = os.path.join(self.base_dir, clean_path)

        # Critical: resolve symlinks and verify prefix
        # Using os.path.realpath to resolve symlinks for true containment
        resolved = os.path.realpath(candidate)

        if not resolved.startswith(self.base_dir):
            return None

        return resolved


sanitizer = PathSanitizer(
    base_dir=BASE_STORAGE_DIR,
    allow_nested=ALLOW_NESTED_PATHS,
    encoding=PATH_ENCODING
)


@app.route('/api/v2/assets/<path:asset_path>', methods=['GET'])
def get_asset(asset_path):
    """Retrieve a mobile asset by path."""
    resolved = sanitizer.resolve_safe_path(asset_path)

    if resolved is None:
        return jsonify({'error': 'Invalid asset path'}), 400

    if not os.path.isfile(resolved):
        return jsonify({'error': 'Asset not found'}), 404

    try:
        with open(resolved, 'rb') as f:
            content = f.read()
        return content, 200
    except IOError:
        return jsonify({'error': 'Read error'}), 500


@app.route('/api/v2/assets/metadata/<path:asset_path>', methods=['GET'])
def get_asset_metadata(asset_path):
    """Get metadata for a mobile asset."""
    resolved = sanitizer.resolve_safe_path(asset_path)

    if resolved is None:
        return jsonify({'error': 'Invalid asset path'}), 400

    if not os.path.exists(resolved):
        return jsonify({'error': 'Asset not found'}), 404

    stat = os.stat(resolved)
    return jsonify({
        'path': asset_path,
        'size': stat.st_size,
        'modified': stat.st_mtime,
    })


if __name__ == '__main__':
    os.makedirs(BASE_STORAGE_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080, debug=False)
